update public.ab_experiments set activo = false where id = 'titular';
insert into public.ab_experiments (id, nombre, hipotesis, variantes, metrica, inicio, activo) values
  ('headline', 'Homepage headline',
   $t$A real customer's words ("I don't know what to wear") persuade better than brand language.$t$,
   $t$[{"id": "a", "texto": "Your stylist, in your pocket."}, {"id": "b", "texto": "You already have something to wear."}]$t$::jsonb,
